<?php
require __DIR__ . '/_bootstrap.php';global $db;$uid=api_require_user();if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')json_err('method','POST required',405);$action=(string)($_POST['action']??'');
if($action==='heal_all'){$db->query("UPDATE survivors SET hp=max_hp,fatigue=0,recovery_progress=0 WHERE userid=$uid");json_out(['ok'=>true,'message'=>'Admin: all survivors healed and rested.']);}
if($action==='finish_all'){$now=time();$db->query("UPDATE builds SET due=$now WHERE userid=$uid");$db->query("UPDATE research_jobs SET due=$now WHERE userid=$uid");$db->query("UPDATE production_jobs SET due=$now WHERE userid=$uid");$db->query("UPDATE training_jobs SET due=$now WHERE userid=$uid");$db->query("UPDATE squads SET arrives_at=$now WHERE userid=$uid AND target_x IS NOT NULL");zv2_refresh($uid);zv2_squads($uid);json_out(['ok'=>true,'message'=>'Admin: construction, research, production, training and squad travel finished.']);}
if($action==='give_resources'){$db->query("UPDATE strongholds SET ressis='9999|9999|9999|9999|9999' WHERE userid=$uid");$db->query("UPDATE research_state SET points=9999 WHERE userid=$uid");for($item=1;$item<=8;$item++){$owned=zv2_item_owned($uid,$item);if($owned<99)zv2_add_item($uid,$item,99-$owned);}json_out(['ok'=>true,'message'=>'Admin: resources, research points and crafting supplies granted.']);}
json_err('bad_action','Unknown admin action.');
